import{_ as e,o as l,c as o,a3 as t}from"./chunks/framework.BveOjhN0.js";const u=JSON.parse('{"title":"Incremental Update","description":"","frontmatter":{"title":"Incremental Update"},"headers":[],"relativePath":"08.plugins/02.incremental-update.md","filePath":"08.plugins/02.incremental-update.md","lastUpdated":1782647142000}'),n={name:"08.plugins/02.incremental-update.md"};function r(i,a,c,d,s,p){return l(),o("div",null,[...a[0]||(a[0]=[t('<p>Incremental updates offer the following advantages:</p><ol><li>Bypass macOS permission restrictions without purchasing a developer account (saving approximately 600 CNY/year).</li><li>If published on other platform app stores, it can theoretically bypass the official update mechanism as well.</li><li>Reduce update package size by approximately 4~10 times, significantly lowering CDN resource costs.</li><li>Users can complete the update by simply restarting, without going through the installation process.</li><li>Full updates delete local data, while incremental updates do not affect local data.</li><li>Supports <code>windows</code>, <code>macOS-intel</code>, and <code>macOS-Apple Silicon</code> platforms.</li><li>The plugin provides several APIs for developers to customize features.</li></ol><h3 id="demo" tabindex="-1">Demo <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;Demo&quot;">​</a></h3><p>The plugin documentation includes a complete demo with page effects, making it easy to use. (Contact the author after purchase)</p><h4 id="cdn" tabindex="-1">CDN <a class="header-anchor" href="#cdn" aria-label="Permalink to &quot;CDN&quot;">​</a></h4><p><a href="https://s.qiniu.com/BbAjMv" target="_blank" rel="noreferrer">Qiniu Cloud</a> offers 10GB of <code>free</code> traffic per month, sufficient for everyday use.</p><h3 id="purchase" tabindex="-1">Purchase <a class="header-anchor" href="#purchase" aria-label="Permalink to &quot;Purchase&quot;">​</a></h3><p>Add on WeChat</p><img style="zoom:20%;" src="https://img01.kaka996.com/ee/wx-2.jpg"><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>The plugin provides several APIs for developers to customize features.</p><h4 id="setconfig" tabindex="-1">setConfig() <a class="header-anchor" href="#setconfig" aria-label="Permalink to &quot;setConfig()&quot;">​</a></h4><p>Set basic configuration</p><h4 id="on-update-available-callback" tabindex="-1">on(&#39;update-available&#39;, callback) <a class="header-anchor" href="#on-update-available-callback" aria-label="Permalink to &quot;on(&#39;update-available&#39;, callback)&quot;">​</a></h4><p>Listen for available update events</p><h4 id="on-update-not-available-callback" tabindex="-1">on(&#39;update-not-available&#39;, callback) <a class="header-anchor" href="#on-update-not-available-callback" aria-label="Permalink to &quot;on(&#39;update-not-available&#39;, callback)&quot;">​</a></h4><p>Listen for no-update-available events</p><h4 id="on-download-progress-callback" tabindex="-1">on(&#39;download-progress&#39;, callback) <a class="header-anchor" href="#on-download-progress-callback" aria-label="Permalink to &quot;on(&#39;download-progress&#39;, callback)&quot;">​</a></h4><p>Listen for download progress events</p><h4 id="on-update-downloaded-callback" tabindex="-1">on(&#39;update-downloaded&#39;, callback) <a class="header-anchor" href="#on-update-downloaded-callback" aria-label="Permalink to &quot;on(&#39;update-downloaded&#39;, callback)&quot;">​</a></h4><p>Listen for download completed events</p><h4 id="on-error-callback" tabindex="-1">on(&#39;error&#39;, callback) <a class="header-anchor" href="#on-error-callback" aria-label="Permalink to &quot;on(&#39;error&#39;, callback)&quot;">​</a></h4><p>Listen for download error events</p><h4 id="checkavailable" tabindex="-1">checkAvailable() <a class="header-anchor" href="#checkavailable" aria-label="Permalink to &quot;checkAvailable()&quot;">​</a></h4><p>Check for updates</p><h4 id="download" tabindex="-1">download() <a class="header-anchor" href="#download" aria-label="Permalink to &quot;download()&quot;">​</a></h4><p>Download</p><h4 id="installapp" tabindex="-1">installApp() <a class="header-anchor" href="#installapp" aria-label="Permalink to &quot;installApp()&quot;">​</a></h4><p>Install</p><h4 id="byteschange" tabindex="-1">bytesChange() <a class="header-anchor" href="#byteschange" aria-label="Permalink to &quot;bytesChange()&quot;">​</a></h4><p>Convert byte count to a readable string</p>',31)])])}const b=e(n,[["render",r]]);export{u as __pageData,b as default};
